/* Finance HQ v0.2: sandboxed demo and optional Google Sheets read-only display. No Sheets writes. */
(()=>{'use strict';
const KEY='finance-hq-demo-v1';
const ICONS={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-6v-7h-4v7H4a1 1 0 0 1-1-1z"/>',list:'<path d="M8 6h13M8 12h13M8 18h13"/><path d="M3 6h.01M3 12h.01M3 18h.01"/>',chart:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="m7 15 4-4 3 2 4-5"/>',card:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20M6 15h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',sparkles:'<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8zM19 16l.8 2.2L22 19l-2.2.8L19 22l-.8-2.2L16 19l2.2-.8zM4 17l.5 1.5L6 19l-1.5.5L4 21l-.5-1.5L2 19l1.5-.5z"/>',bars:'<path d="M4 20V11M10 20V4M16 20v-7M22 20V8"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.6 1.6 0 0 0 .3 1.8l.1.1-2 2-.1-.1a1.6 1.6 0 0 0-1.8-.3l-.1.1V21h-3v-.2a1.6 1.6 0 0 0-1-1.4 1.6 1.6 0 0 0-1.7.3l-.2.1-2-2 .1-.1a1.6 1.6 0 0 0 .3-1.8l-.1-.1H6v-3h.2a1.6 1.6 0 0 0 1.4-1 1.6 1.6 0 0 0-.3-1.7l-.1-.2 2-2 .1.1a1.6 1.6 0 0 0 1.8.3l.1-.1V6h3v.2a1.6 1.6 0 0 0 1 1.4 1.6 1.6 0 0 0 1.7-.3l.2-.1 2 2-.1.1a1.6 1.6 0 0 0-.3 1.8l.1.1H21v3h-.2a1.6 1.6 0 0 0-1.4 1z" transform="translate(-1 -1)"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 18 6-6-6-6"/>',arrow:'<path d="m5 12 14 0m-6-6 6 6-6 6"/>',wallet:'<rect x="3" y="6" width="18" height="15" rx="2"/><path d="M3 9V5a2 2 0 0 1 2-2h13M16 15h5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',receipt:'<path d="M5 3h14v18l-3-2-4 2-4-2-3 2zM9 8h6M9 12h6"/>',fuel:'<path d="M4 20V5a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v15M3 20h14M6 8h8M16 10h2l3 3v5a2 2 0 0 1-4 0v-3"/>',coffee:'<path d="M4 8h14v8a6 6 0 0 1-6 6h-2a6 6 0 0 1-6-6zM18 9h2a3 3 0 0 1 0 6h-2M8 2v3M13 2v3"/>',bag:'<path d="M4 8h16l-1 13H5zM9 10V6a3 3 0 0 1 6 0v4"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',check:'<path d="m5 12 4 4L19 6"/>',warning:'<path d="m12 3 10 18H2zM12 9v5M12 17h.01"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 18v3h16v-3"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',trash:'<path d="M3 6h18M8 6V4h8v2M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',x:'<path d="M5 5 19 19M19 5 5 19"/>',edit:'<path d="M12 20h9M4 20l4-1 11-11-3-3L5 16zM14 7l3 3"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v5M12 7h.01"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 12a7 7 0 0 1 12-5l3 5M4 12l3 5a7 7 0 0 0 12-5"/>',trend:'<path d="m3 17 6-6 4 4 8-8M15 7h6v6"/>',bank:'<path d="m2 10 10-7 10 7zM4 10v10M9 10v10M15 10v10M20 10v10M2 21h20"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',heart:'<path d="M20 5a5 5 0 0 0-8 0 5 5 0 0 0-8 0c-3 3 0 8 8 15 8-7 11-12 8-15z"/>',plane:'<path d="m22 2-8 20-4-8-8-4zM10 14 22 2"/>',filter:'<path d="M4 6h16M7 12h10M10 18h4"/>',dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',shield:'<path d="m12 2 8 4v6c0 6-4 9-8 10-4-1-8-4-8-10V6zM8 12l3 3 5-6"/>'};
function icon(k){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ICONS[k]||ICONS.wallet}</svg>`;}
const CAT={Food:{color:'#efc17d',ico:'coffee'},Transport:{color:'#79a9fa',ico:'fuel'},Shopping:{color:'#ff8e96',ico:'bag'},Bills:{color:'#a99afa',ico:'bolt'},Fitness:{color:'#50e0b5',ico:'heart'},Subscriptions:{color:'#9ac6ec',ico:'calendar'},Travel:{color:'#89d0dd',ico:'plane'},Other:{color:'#9bafc4',ico:'receipt'}};
const METHODS=['GCash','Cash','BDO Visa Signature','BDO Visa Signature Virtual','BDO AMEX Explorer','BDO Diamond UnionPay','BPI Visa Signature','Security Bank Platinum','EastWest Gold Mastercard','Metrobank Visa Platinum'];
const demoData=()=>({version:1,settings:{cap:48000,reserve:17500,savings:10000,activeCycle:'2026-10-16'},transactions:[
{id:'t101',date:'2026-11-05',name:'Sample coffee stop',category:'Food',amount:195,method:'GCash',bucket:'flex',paidBy:'me',otherShare:0,repaid:0,person:''},
{id:'t102',date:'2026-11-04',name:'Example groceries',category:'Food',amount:1450,method:'BDO Visa Signature',bucket:'flex',paidBy:'me',otherShare:0,repaid:0,person:''},
{id:'t103',date:'2026-11-03',name:'Demo fuel purchase',category:'Transport',amount:2500,method:'GCash',bucket:'reserve',paidBy:'me',otherShare:0,repaid:0,person:''},
{id:'t104',date:'2026-11-02',name:'Sample group dinner',category:'Food',amount:1900,method:'BDO Visa Signature',bucket:'flex',paidBy:'me',otherShare:950,repaid:400,person:'Alex (demo)'},
{id:'t105',date:'2026-11-01',name:'Example mobile plan',category:'Bills',amount:650,method:'BDO Visa Signature Virtual',bucket:'reserve',paidBy:'me',otherShare:0,repaid:0,person:''},
{id:'t106',date:'2026-10-30',name:'Demo gym membership',category:'Fitness',amount:2300,method:'BDO Visa Signature',bucket:'reserve',paidBy:'me',otherShare:0,repaid:0,person:''},
{id:'t107',date:'2026-10-28',name:'Example parking',category:'Transport',amount:90,method:'Cash',bucket:'flex',paidBy:'me',otherShare:0,repaid:0,person:''},
{id:'t108',date:'2026-10-26',name:'Demo insurance payment',category:'Bills',amount:3050,method:'BDO Visa Signature',bucket:'reserve',paidBy:'me',otherShare:0,repaid:0,person:''},
{id:'t109',date:'2026-10-24',name:'Sample shopping order',category:'Shopping',amount:1200,method:'BDO Diamond UnionPay',bucket:'flex',paidBy:'me',otherShare:0,repaid:0,person:''},
{id:'t110',date:'2026-10-21',name:'Example lunch',category:'Food',amount:480,method:'GCash',bucket:'flex',paidBy:'me',otherShare:0,repaid:0,person:''},
{id:'t111',date:'2026-10-19',name:'Sample café split',category:'Food',amount:720,method:'GCash',bucket:'flex',paidBy:'other',otherShare:280,repaid:0,person:'Casey (demo)'},
{id:'t112',date:'2026-10-18',name:'Demo streaming subscription',category:'Subscriptions',amount:399,method:'BDO Visa Signature Virtual',bucket:'reserve',paidBy:'me',otherShare:0,repaid:0,person:''},
{id:'t113',date:'2026-10-16',name:'Sample household supplies',category:'Shopping',amount:1800,method:'Cash',bucket:'flex',paidBy:'me',otherShare:0,repaid:0,person:''}],
cards:[{id:'c1',name:'BDO Visa Signature',sub:'Primary card · example billing',amount:15500,paid:6000,due:'2026-11-17',color:'#63ddc3'},{id:'c2',name:'BDO AMEX Explorer',sub:'Travel & rewards · example billing',amount:6800,paid:0,due:'2026-11-26',color:'#ab9bf3'},{id:'c3',name:'BPI Visa Signature',sub:'Backup card · example billing',amount:3400,paid:0,due:'2026-12-01',color:'#86b3fa'},{id:'c4',name:'BDO Diamond UnionPay',sub:'Backup card · example billing',amount:1200,paid:1200,due:'2026-12-05',color:'#f0c682'}],
bills:[{id:'b1',name:'Example electricity',category:'Utilities',amount:4750,due:'2026-11-12',paid:false,ico:'bolt'},{id:'b2',name:'Example home internet',category:'Internet',amount:2199,due:'2026-11-15',paid:false,ico:'wallet'},{id:'b3',name:'Demo gym',category:'Fitness',amount:2300,due:'2026-11-01',paid:true,ico:'heart'},{id:'b4',name:'Example streaming',category:'Subscription',amount:399,due:'2026-11-18',paid:false,ico:'calendar'},{id:'b5',name:'Sample insurance installment',category:'Installment',amount:3200,due:'2026-11-20',paid:false,ico:'shield'},{id:'b6',name:'Example phone plan',category:'Mobile',amount:650,due:'2026-11-09',paid:true,ico:'wallet'}],
rebates:[{id:'r1',name:'Sample travel cashback',issuer:'Example card promotion',target:10000,progress:7600,expected:500,credited:false},{id:'r2',name:'Demo shopping rebate',issuer:'Example card promotion',target:5000,progress:5000,expected:300,credited:false},{id:'r3',name:'Sample dining rewards',issuer:'Example card promotion',target:3000,progress:3000,expected:150,credited:true}],paymentLog:[]});
let state=readState();let view='home',filterCategory='all',searchTerm='',modalOpen=false,toastTimer=null,previousFocus=null;
function readState(){try{const v=localStorage.getItem(KEY);if(v){const data=JSON.parse(v);if(validData(data))return data;}}catch{}return demoData();}
function validData(v){return v&&v.version===1&&v.settings&&Array.isArray(v.transactions)&&Array.isArray(v.cards)&&Array.isArray(v.bills)&&Array.isArray(v.rebates)&&Array.isArray(v.paymentLog)&&v.transactions.length<10000;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Local storage unavailable: changes may not be saved.');}}
const num=n=>Number.isFinite(Number(n))?Number(n):0, money=n=>'₱'+num(n).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2}), compact=n=>'₱'+num(n).toLocaleString('en-PH',{maximumFractionDigits:0}), pct=n=>Math.max(0,Math.min(100,num(n))), e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function niceDate(d){if(!/^\d{4}-\d{2}-\d{2}$/.test(String(d)))return 'No date';const date=new Date(`${d}T12:00:00`);return Number.isNaN(date.getTime())?'No date':date.toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'});}
function shortDate(d){return niceDate(d).replace(', 2026','');}
function balance(t){const amount=num(t.amount),other=Math.min(amount,Math.max(0,num(t.otherShare))),rep=Math.max(0,num(t.repaid));return t.paidBy==='other'?Math.max(0,amount-other-rep):Math.max(0,other-rep);}
function impact(t){const amount=num(t.amount),other=Math.min(amount,Math.max(0,num(t.otherShare)));return t.paidBy==='other'?amount-other:Math.max(0,amount-Math.max(0,num(t.repaid)));}
function sums(){const reserveSpent=activeTx().filter(t=>t.bucket==='reserve').reduce((n,t)=>n+impact(t),0),flexSpent=activeTx().filter(t=>t.bucket!=='reserve').reduce((n,t)=>n+impact(t),0),cap=num(state.settings.cap),reserve=num(state.settings.reserve),savings=num(state.settings.savings),overage=Math.max(0,reserveSpent-reserve),safe=Math.max(0,cap-reserve-savings-flexSpent-overage),receivable=state.transactions.filter(t=>t.paidBy==='me').reduce((n,t)=>n+balance(t),0),payable=state.transactions.filter(t=>t.paidBy==='other').reduce((n,t)=>n+balance(t),0),spend=reserveSpent+flexSpent;return {cap,reserve,savings,reserveSpent,flexSpent,overage,safe,receivable,payable,spend,remaining:cap-spend,reserveLeft:Math.max(0,reserve-reserveSpent),budgetUsage:cap?spend/cap*100:0};}
function cycleStart(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return '2026-10-16';const [y,m,d]=date.split('-').map(Number);let dt=new Date(Date.UTC(y,d>=16?m-1:m-2,16));return `${dt.getUTCFullYear()}-${String(dt.getUTCMonth()+1).padStart(2,'0')}-16`;}
function cycleLabel(start){const [y,m]=start.split('-').map(Number),a=new Date(Date.UTC(y,m-1,16)),b=new Date(Date.UTC(y,m,15));return `${a.toLocaleDateString('en-PH',{month:'short',day:'numeric',timeZone:'UTC'})} – ${b.toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'})}`;}
function cycleSelect(){let options='';for(let y=2026;y<=2027;y++)for(let m=1;m<=12;m++){if(y===2026&&m<7)continue;const key=`${y}-${String(m).padStart(2,'0')}-16`;options+=`<option value="${key}" ${state.settings.activeCycle===key?'selected':''}>${cycleLabel(key)}</option>`;}return `<select id="cycleSelect" aria-label="Choose cutoff cycle" style="min-width:195px">${options}</select>`;}
function activeTx(){const chosen=state.settings.activeCycle||'2026-10-16';return state.transactions.filter(t=>cycleStart(t.date)===chosen);}
function sortTx(arr=state.transactions){return [...arr].sort((a,b)=>String(b.date).localeCompare(String(a.date))||String(b.id).localeCompare(String(a.id)));}
function categoryIcon(category){const c=CAT[category]||CAT.Other;return `<div class="trans-icon ${category==='Food'?'food':category==='Transport'?'transport':category==='Shopping'?'shopping':category==='Bills'||category==='Subscriptions'?'bills':category==='Fitness'?'fitness':''}">${icon(c.ico)}</div>`;}
function heading(kicker,title,description,actions=''){return `<div class="heading-row"><div><div class="eyebrow">${e(kicker)}</div><h1>${e(title)}</h1><p>${e(description)}</p></div><div class="heading-actions">${actions}</div></div>`;}
function demoStrip(){return `<div class="demo-strip">${icon('info')}<span><strong>DEMO DATA ONLY.</strong> Every amount and merchant on this screen is invented. Nothing is synced to your Expense Tracker or bank accounts.</span><button data-live="live">Connect live Sheets</button></div>`;}
function cardStat(label,value,foot,ic,clazz=''){return `<div class="kpi"><div class="kpi-label">${e(label)}${icon(ic)}</div><div class="kpi-value ${clazz}">${value}</div><div class="kpi-foot">${e(foot)}</div></div>`;}
function panelHeader(title,sub='',link='',destination=''){return `<div class="panel-heading"><div><h2>${e(title)}</h2>${sub?`<p>${e(sub)}</p>`:''}</div>${link?`<button class="text-action" data-nav="${destination}">${e(link)} ${icon('arrow')}</button>`:''}</div>`;}
function txRow(t,click=true){return `<div class="trans-row ${click?'trans-row-click':''}" ${click?`data-action="detail" data-id="${e(t.id)}" role="button" tabindex="0"`:''}>${categoryIcon(t.category)}<div class="trans-main"><div class="trans-name">${e(t.name)}</div><div class="trans-sub">${e(t.category)} · ${e(t.method)} · ${e(shortDate(t.date))}${t.otherShare>0?' · Shared':''}</div></div><div class="trans-value">${money(t.amount)}<span>${t.paidBy==='other'?'Paid by friend':t.bucket==='reserve'?'From reserve':'Expense'}</span></div></div>`;}
function breakout(){const s=sums(),available=Math.max(0,s.cap-s.reserve-s.savings),flex=Math.min(available,s.flexSpent+s.overage),left=Math.max(0,available-flex),vals=[{name:'Reserved obligations',v:s.reserve,c:'#ad9afc'},{name:'Savings goal',v:s.savings,c:'#f4c57b'},{name:'Discretionary used',v:flex,c:'#77a6ff'},{name:'Safe to spend',v:left,c:'#55e0b5'}],total=vals.reduce((n,x)=>n+x.v,0)||1;return `<div class="bar-stack">${vals.map(x=>`<div title="${e(x.name)} ${money(x.v)}" style="width:${x.v/total*100}%;background:${x.c}"></div>`).join('')}</div><div class="breakdown-legend">${vals.map(x=>`<div class="legend-item"><div class="legend-name"><i class="legend-color" style="background:${x.c}"></i>${e(x.name)}</div><strong>${compact(x.v)}</strong></div>`).join('')}</div>`;}
function home(){const s=sums(),recent=sortTx(activeTx()).slice(0,5);return heading('YOUR MONEY, CLEARLY','Good to see you.','An organized view of your spending. No spreadsheet gymnastics required.',`${cycleSelect()}`)+demoStrip()+`<div class="dashboard-hero"><section class="hero-card"><div class="metric-name">${icon('wallet')} YOUR SAFE-TO-SPEND BALANCE</div><div class="hero-number">${money(s.safe)}</div><p class="hero-hint">After planned reserves, savings and current spending.</p><div class="hero-progress"><div style="width:${pct((s.cap-s.reserve-s.savings)?s.safe/(s.cap-s.reserve-s.savings)*100:0)}%"></div></div><div class="hero-bottom"><span>Cycle cap <strong>${compact(s.cap)}</strong></span><span>Savings target <strong>${compact(s.savings)}</strong></span><span>Remaining <strong>${compact(s.remaining)}</strong></span></div></section><section class="reserve-card"><div><div class="section-kicker">Money already spoken for</div><div class="reserve-big">${money(s.reserve)}</div><p class="reserve-sub">Reserved for recurring bills and obligations</p></div><div class="allocation-list"><div class="allocation-line"><span><i class="dot dot-purple"></i>Reserve used</span><strong>${compact(s.reserveSpent)}</strong></div><div class="allocation-line"><span><i class="dot dot-gold"></i>Reserve still allocated</span><strong>${compact(s.reserveLeft)}</strong></div><div class="allocation-line"><span><i class="dot dot-blue"></i>Discretionary impact</span><strong>${compact(s.flexSpent)}</strong></div></div></section></div><div class="kpi-grid">${cardStat('Budget impact',money(s.spend),'Selected sample cutoff','trend')}${cardStat('Still collectible',money(s.receivable),'Shared expenses fronted','users','positive')}${cardStat('I still owe',money(s.payable),'Unpaid personal share','wallet','amber')}${cardStat('Upcoming card balances',money(state.cards.reduce((n,c)=>n+Math.max(0,c.amount-c.paid),0)),'Sample statement balances','card')}</div><div class="action-strip"><button class="action-tile" data-action="add"><span class="action-icon">${icon('plus')}</span>Add transaction</button><button class="action-tile" data-nav="shared"><span class="action-icon">${icon('users')}</span>Split expenses</button><button class="action-tile" data-nav="cards"><span class="action-icon">${icon('card')}</span>Card payments</button><button class="action-tile" data-nav="rebates"><span class="action-icon">${icon('sparkles')}</span>Check rebates</button></div><div class="two-col"><section class="panel panel-pad">${panelHeader('Where the money goes','A simple breakdown of the current sample cutoff','Full budget','budget')}${breakout()}<div class="info-note">${icon('info')} Fronted shared costs affect safe-to-spend until repayments are verified. Card bill payments are tracked separately, not treated as new spending.</div></section><section class="panel panel-pad">${panelHeader('Recent activity','Your five latest recorded items','All activity','activity')}<div class="mini-list">${recent.map(txRow).join('')||empty('No demo expenses yet.','Add a sample transaction to start.')}</div></section></div><section class="panel panel-pad">${panelHeader('Your next steps','A few useful things to review','View bills','bills')}<div class="action-strip" style="margin:0"><button class="action-tile" data-nav="bills">${icon('calendar')} Check upcoming bills</button><button class="action-tile" data-nav="cards">${icon('card')} Review card dues</button><button class="action-tile" data-nav="reports">${icon('bars')} Explore categories</button><button class="action-tile" data-nav="settings">${icon('download')} Back up demo data</button></div></section>`;}
function empty(title,body){return `<div class="empty">${icon('receipt')}<strong>${e(title)}</strong>${e(body)}</div>`;}
function activity(){return heading('COMPLETE TRANSACTION HISTORY','Every peso, accounted for.','Log purchases with the right date, payment method, and shared split.',`<button class="btn-primary" data-action="add">${icon('plus')} Add expense</button>`)+demoStrip()+`<div class="mini-summary-grid">${cardStat('Recorded entries',String(state.transactions.length),'Demo ledger entries','receipt')}${cardStat('Total cutoff impact',money(sums().spend),'After verified shared repayments','wallet')}${cardStat('Awaiting repayment',money(sums().receivable),'Only unpaid fronted balances','users','positive')}</div><div class="panel"><div class="table-controls"><div class="search-wrap">${icon('search')}<input id="transactionSearch" value="${e(searchTerm)}" placeholder="Search description, method or person..." aria-label="Search transactions"></div><select id="categorySelect" aria-label="Filter category"><option value="all">All categories</option>${Object.keys(CAT).map(c=>`<option value="${c}" ${filterCategory===c?'selected':''}>${c}</option>`).join('')}</select><button class="mini-button" data-action="csv">${icon('download')} Export CSV</button></div><div id="transactionsTableWrap">${transactionsTable()}</div></div><div class="info-note">${icon('info')} Expense date is the transaction date, not statement posting date. Repayments reduce temporary budget impact only when marked verified.</div>`;}
function transactionsTable(){const query=searchTerm.trim().toLowerCase(),ts=sortTx().filter(t=>(filterCategory==='all'||t.category===filterCategory)&&(!query||[t.name,t.category,t.method,t.person,t.date].some(v=>String(v||'').toLowerCase().includes(query))));return ts.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Transaction</th><th>Payment</th><th>Amount</th><th>Budget impact</th><th>Details</th></tr></thead><tbody>${ts.map(t=>`<tr><td class="muted-cell">${e(niceDate(t.date))}</td><td class="strong-cell">${e(t.name)}<div class="table-meta">${e(t.category)} · ${t.bucket==='reserve'?'Reserved':'Discretionary'}</div></td><td>${e(t.method)}</td><td class="amount-cell">${money(t.amount)}</td><td>${money(impact(t))}</td><td><button class="small-action" data-action="detail" data-id="${e(t.id)}">View →</button></td></tr>`).join('')}</tbody></table></div>`:empty('No matching transactions','Try a different keyword or category.');}
function budget(){const s=sums();return heading('BUDGET & SAVINGS','Know your limits. Keep your freedom.','A cutoff-based view, not a calendar-month shortcut.',`${cycleSelect()}`)+demoStrip()+`<div class="mini-summary-grid">${cardStat('Budget cap',money(s.cap),'Selected sample cutoff','wallet')}${cardStat('Safe to spend',money(s.safe),'Conservative spendable balance','check','positive')}${cardStat('Actual impact',money(s.spend),'Reserved + discretionary','trend')}</div><div class="two-col"><section class="panel panel-pad">${panelHeader('Your cutoff allocation','Where the ₱48k sample cap goes')}${breakout()}<div class="info-note">${icon('info')} Safe to spend = max(0, cap − reserve − savings − discretionary impact − any reserve overspend). Reserve purchases use their existing allocation first.</div></section><section class="panel panel-pad">${panelHeader('Reserve tracking','Allocated versus already recorded')}${metricRow('Fixed reserved amount',s.reserve)}${metricRow('Recorded reserved expenses',s.reserveSpent)}${metricRow('Still reserved, not spent',s.reserveLeft)}${metricRow('Over reserve',s.overage,'negative')}${metricRow('Savings target',s.savings)}<button class="btn-secondary" style="margin-top:16px" data-action="budgetSettings">${icon('settings')} Edit demo budget</button></section></div><section class="panel panel-pad">${panelHeader('Budget guardrails','Preview calculations follow the expense tracker rules')}<ul class="help-list"><li><strong>No credit-card double counting.</strong> Purchases belong to the transaction ledger. Payments toward card statements live separately.</li><li><strong>Shared expenses stay real.</strong> Fronted money remains in the budget impact until verified repayment arrives.</li><li><strong>Others’ unpaid installments</strong> should not be counted as your personal installment reserve.</li><li><strong>Every cutoff matters.</strong> The real app will read the correct 16th-to-15th cycle from Google Sheets.</li></ul></section>`;}
function metricRow(a,b,cls=''){return `<div class="allocation-line" style="border-bottom:1px solid var(--stroke);padding:12px 0"><span>${e(a)}</span><strong class="${cls}">${money(b)}</strong></div>`;}
function cards(){const due=state.cards.reduce((n,c)=>n+Math.max(0,c.amount-c.paid),0);return heading('CREDIT CARDS','Statements, without the guesswork.','Billing, due dates and issuer payments live outside the purchase ledger.')+demoStrip()+`<div class="mini-summary-grid">${cardStat('Unpaid statements',money(due),'Across example cards','card')}${cardStat('Payments recorded',money(state.cards.reduce((n,c)=>n+c.paid,0)),'Demo statement allocations','check','positive')}${cardStat('Cards tracked',String(state.cards.length),'Sample cards','wallet')}</div><div class="card-grid">${state.cards.map(c=>`<article class="credit-product" style="border-top:3px solid ${e(c.color)}"><div class="card-top"><small>EXAMPLE STATEMENT</small>${icon('card')}</div><div class="card-issuer">${e(c.name)}</div><div class="card-sub">${e(c.sub)}</div><div class="card-amount">${money(Math.max(0,c.amount-c.paid))}</div><div class="card-bottom"><div>Due <strong style="color:#e6f5f9">${e(niceDate(c.due))}</strong> · ${c.paid>=c.amount?'Paid':'Unpaid'}</div><button class="card-pay" data-action="cardPay" data-id="${e(c.id)}" ${c.paid>=c.amount?'disabled':''}>Record payment</button></div></article>`).join('')}</div><section class="panel panel-pad">${panelHeader('Payment records','Payments do not create duplicate purchase expenses')}<div class="mini-list">${state.paymentLog.length?state.paymentLog.slice().reverse().map(p=>{const c=state.cards.find(x=>x.id===p.cardId);return `<div class="trans-row"><div class="trans-icon">${icon('check')}</div><div class="trans-main"><div class="trans-name">${e(c?.name||'Card payment')}</div><div class="trans-sub">${e(niceDate(p.date))} · Demo issuer payment</div></div><div class="trans-value positive">${money(p.amount)}</div></div>`;}).join(''):empty('No new payments recorded','The seeded statement balances are examples; use Record payment to try the workflow.')}</div><div class="info-note">${icon('shield')} Statement line reconciliation and issuer payment matching will connect to the actual 2026/2027 tracker only after safe read access and audit checks are built.</div></section>`;}
function bills(){const due=state.bills.filter(b=>!b.paid).reduce((n,b)=>n+b.amount,0);return heading('BILLS & INSTALLMENTS','Nothing slips through.','Subscriptions, utilities, and installment schedules in one place.')+demoStrip()+`<div class="mini-summary-grid">${cardStat('Unpaid bills',money(due),'Status in demo bills list','calendar','amber')}${cardStat('Paid bills',String(state.bills.filter(b=>b.paid).length),'Of '+state.bills.length+' example bills','check','positive')}${cardStat('Upcoming obligations',String(state.bills.filter(b=>!b.paid).length),'Items not yet marked paid','clock')}</div><div class="panel panel-pad">${panelHeader('Recurring obligations','Toggle a status to try the bills workflow')}<div class="bills-grid">${state.bills.map(b=>`<div class="bill-row"><div class="bill-symbol">${icon(b.ico||'calendar')}</div><div><h3>${e(b.name)}</h3><p>${e(b.category)} · Due ${e(niceDate(b.due))}</p></div><div class="bill-trail"><strong>${money(b.amount)}</strong><button class="small-action" data-action="billToggle" data-id="${e(b.id)}">${b.paid?'✓ Paid':'Mark paid'}</button></div></div>`).join('')}</div><div class="info-note">${icon('info')} Marking a bill paid in this preview only changes its checklist status. It does not post a second expense or record a card payment.</div></div>`;}
function shared(){const front=sortTx().filter(t=>t.paidBy==='me'&&num(t.otherShare)>0),owe=sortTx().filter(t=>t.paidBy==='other'&&impact(t)>0),s=sums();return heading('SHARED EXPENSES','Less chasing. More clarity.','Keep what you fronted separate from what you owe.')+demoStrip()+`<div class="mini-summary-grid">${cardStat('Still collectible',money(s.receivable),'Paid by you, not yet reimbursed','users','positive')}${cardStat('Still payable',money(s.payable),'Your share fronted by someone else','wallet','amber')}${cardStat('Shared records',String(front.length+owe.length),'Demo sample splits','receipt')}</div><div class="two-col"><section class="panel panel-pad">${panelHeader('They owe you','Verified repayments reduce outstanding balance')}<div>${front.length?front.map(t=>sharedRow(t,'receive')).join(''):empty('No receivables','Add a shared expense that you paid first.')}</div></section><section class="panel panel-pad">${panelHeader('You owe them','Personal shares fronted by a friend')}<div>${owe.length?owe.map(t=>sharedRow(t,'pay')).join(''):empty('No payables','Record a shared transaction paid by someone else.')}</div></section></div><div class="info-note">${icon('info')} Demo payments are per transaction. The real app will match received payments to specific shared charges and reconcile them with the existing Shared Expenses Portal.</div>`;}
function sharedRow(t,kind){const amount=balance(t);return `<div class="shared-person"><div class="person-circle">${e((t.person||'?').trim().slice(0,1).toUpperCase())}</div><div class="person-detail"><strong>${e(t.person||'Unspecified')}</strong><small>${e(t.name)} · ${e(shortDate(t.date))}</small><div class="stacked-values"><span class="tag">Split: ${money(kind==='receive'?t.otherShare:t.amount-t.otherShare)}</span><span class="tag">Verified: ${money(t.repaid)}</span></div></div><div style="text-align:right"><div class="person-number ${kind==='receive'?'positive':'amber'}">${money(amount)}</div><button class="small-action" data-action="repay" data-id="${e(t.id)}" ${amount<=0?'disabled':''}>${amount<=0?'Settled':kind==='receive'?'Record received':'Record paid'}</button></div></div>`;}
function rebates(){const pending=state.rebates.filter(r=>!r.credited&&r.progress>=r.target).reduce((n,r)=>n+r.expected,0),credited=state.rebates.filter(r=>r.credited).reduce((n,r)=>n+r.expected,0);return heading('REBATES & REWARDS','Rewards should not disappear.','Track promo qualification and credits separately from transaction spending.')+demoStrip()+`<div class="mini-summary-grid">${cardStat('Eligible, pending',money(pending),'Qualified sample promotions','clock','amber')}${cardStat('Credited',money(credited),'Verified status in demo','check','positive')}${cardStat('Active promotions',String(state.rebates.length),'Fictional examples','sparkles')}</div><section class="panel panel-pad">${panelHeader('Promo tracker','Status, threshold and credit verification')}<div>${state.rebates.map(r=>`<div class="rebate-row"><div class="rebate-top"><div><h3>${e(r.name)}</h3><p>${e(r.issuer)} · Threshold ${money(r.target)}</p></div><div class="rebate-amount">${money(r.expected)}</div></div><div class="rebate-track"><div style="width:${pct(r.target?r.progress/r.target*100:0)}%"></div></div><div class="rebate-footer"><span>Qualifying sample spend: ${money(r.progress)} · ${Math.min(100,Math.round((r.target?r.progress/r.target:0)*100))}%</span><button class="small-action" data-action="rebateToggle" data-id="${e(r.id)}">${r.credited?'✓ Credited · Undo':'Mark credited'}</button></div></div>`).join('')}</div><div class="info-note">${icon('info')} Marking a cashback credited in this preview changes only its rebate status. It does not invent a bank credit or silently reduce expense totals.</div></section>`;}
function reports(){const byCat=Object.keys(CAT).map(name=>({name,v:activeTx().filter(t=>t.category===name).reduce((n,t)=>n+impact(t),0),color:CAT[name].color})).filter(x=>x.v>0).sort((a,b)=>b.v-a.v),total=byCat.reduce((n,x)=>n+x.v,0),denom=total||1;let offset=0;const stops=byCat.map(x=>{const st=offset;offset+=x.v/denom*100;return `${x.color} ${st.toFixed(3)}% ${offset.toFixed(3)}%`;}).join(',');const byMethod=[...new Set(activeTx().map(t=>t.method))].map(name=>({name,v:activeTx().filter(t=>t.method===name).reduce((n,t)=>n+impact(t),0)})).sort((a,b)=>b.v-a.v);return heading('FINANCIAL REPORTS','Find the pattern.','An at-a-glance view of the selected sample cutoff and spending categories.')+demoStrip()+`<div class="two-col"><section class="panel panel-pad">${panelHeader('Spending by category','Temporary shared fronting is included in budget impact')}<div class="category-chart"><div class="donut" style="background:conic-gradient(${stops||'#1b3448 0% 100%'})"><div class="donut-center"><strong>${compact(total)}</strong><small>Total impact</small></div></div><div class="chart-legend">${byCat.map(x=>`<div class="legend-line"><i class="legend-color" style="background:${x.color}"></i><span>${e(x.name)}</span><strong>${Math.round(x.v/denom*100)}%</strong></div>`).join('')}</div></div></section><section class="panel panel-pad">${panelHeader('Payment method usage','Sample expense budget impact by payment method')}${byMethod.map(x=>`<div class="horizontal-bar"><div class="bar-label">${e(x.name)}</div><div class="bar-bg"><div style="width:${pct(x.v/(byMethod[0]?.v||1)*100)}%"></div></div><div class="bar-num">${compact(x.v)}</div></div>`).join('')}</section></div><section class="panel panel-pad">${panelHeader('Finance HQ rules','How the app avoids misleading numbers')}<ul class="help-list"><li><strong>Transaction date</strong> determines which 16th-to-15th cutoff owns a purchase.</li><li><strong>Issuer statement payment</strong> is repayment of a liability, not a second expense.</li><li><strong>Third-party installment</strong> stays separate from your personal reserve while the other person remains responsible.</li><li><strong>Cashback is recognized only when verified.</strong> Expected rebates are shown as pending, not as spendable cash.</li><li><strong>Historical data</strong> must be mapped from exact existing tracker formulas, not rebuilt from assumptions.</li></ul></section>`;}
function settings(){const s=state.settings;return heading('PREFERENCES & PRIVACY','Your data stays yours.','Review this prototype’s limits and try the demo safely.')+demoStrip()+`<section class="panel panel-pad section-spacing"><h2>Connect your actual Expense Tracker</h2><p class="fineprint">Switch to live Google Sheets read-only mode. OAuth configuration is required; no data from the real tracker is bundled with this demo.</p><button class="btn-primary" data-live="live">Set up live dashboard →</button></section>`+`<div class="settings-grid"><section class="setting-card"><h3>Demo budget settings</h3><p>Adjust the sample cap, reserve and savings goal. This changes only the local preview.</p><div class="settings-form"><div class="form-field"><label>Cutoff cap (₱)</label><input id="capSetting" type="number" min="0" step="0.01" value="${s.cap}"></div><div class="form-field"><label>Reserved obligations (₱)</label><input id="reserveSetting" type="number" min="0" step="0.01" value="${s.reserve}"></div><div class="form-field"><label>Savings goal (₱)</label><input id="savingsSetting" type="number" min="0" step="0.01" value="${s.savings}"></div></div><button class="btn-primary" style="margin-top:17px" data-action="saveSettings">Save demo settings</button></section><section class="setting-card"><h3>Export & backup</h3><p>Download a local copy of the demo. JSON backups can be re-imported into this preview. No uploads to external servers.</p><button class="btn-secondary" data-action="json">${icon('download')} Export JSON</button><button class="btn-secondary" data-action="csv">${icon('download')} Export CSV</button><button class="btn-secondary" data-action="import">${icon('upload')} Import JSON</button></section><section class="setting-card"><h3>Security & sync</h3><p>This is a prototype, not the secure finance integration. Data is stored in your browser and may be visible to anyone who can access that browser profile.</p><span class="status good">${icon('lock')} No external API calls</span><div class="page-spacer"></div><span class="status neutral">${icon('info')} Google Sheets disconnected</span><div class="page-spacer"></div><span class="status neutral">${icon('info')} No bank connections</span></section><section class="setting-card"><h3>Reset the playground</h3><p>Clear local changes and restore the original fictional demo data. Your actual Google Sheets, China app and Shared Expenses Portal are unaffected.</p><button class="danger-button" data-action="reset">${icon('refresh')} Reset demo data</button></section></div>`;}
const pages={home,activity,budget,cards,bills,shared,rebates,reports,settings},pageTitles={home:'Overview',activity:'Transactions',budget:'Budget & Savings',cards:'Credit Cards',bills:'Bills & Installments',shared:'Shared Expenses',rebates:'Rebates & Rewards',reports:'Reports',settings:'Settings'};
function render(){const root=document.getElementById('pageRoot'),isLive=!!window.FinanceHQLive?.isLive?.();root.innerHTML=isLive?window.FinanceHQLive.render(view):(pages[view]||home)();document.getElementById('topbarPage').textContent=pageTitles[view]||'Overview';const add=document.getElementById('topAdd');if(add){const t=add.querySelector('span:last-child');if(t)t.textContent=isLive?window.FinanceHQLive.primaryActionLabel():'New expense';}const mobileAdd=document.getElementById('mobileAdd');if(mobileAdd){mobileAdd.setAttribute('aria-label',isLive?window.FinanceHQLive.primaryActionLabel():'Add demo expense');mobileAdd.innerHTML=icon(isLive?'refresh':'plus');}const priv=document.querySelector('.privacy-chip');if(priv)priv.textContent=isLive?'Google Sheets · Read-only':'Private preview';const bottom=document.querySelector('.private-pill');if(bottom)bottom.textContent=isLive?'GOOGLE READ-ONLY MODE':'LOCAL DEMO MODE';const note=document.querySelector('.side-bottom p');if(note)note.textContent=isLive?'No Sheets editing. Your records are fetched only after authorization.':'Private sample data. No bank or Google Sheets writes.';document.querySelectorAll('[data-nav]').forEach(b=>{const active=b.dataset.nav===view;b.classList.toggle('selected',active&&b.classList.contains('nav-item'));b.classList.toggle('active',active&&b.closest('.bottom-nav'));if(active&&b.classList.contains('nav-item'))b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
function navigate(dest){if(modalOpen)closeModal();view=pages[dest]?dest:'home';render();window.scrollTo({top:0,behavior:'instant'});try{history.replaceState(null,'','#'+view);}catch{}}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3400);}
function modal(title,subtitle,body,footer){previousFocus=document.activeElement;modalOpen=true;document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" role="presentation" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="modal-header"><div><div class="eyebrow">FINANCE HQ · LOCAL DEMO</div><h2>${e(title)}</h2><p>${e(subtitle)}</p></div><button class="close-button" data-action="close" aria-label="Close dialog">${icon('x')}</button></div><div class="modal-body">${body}</div><div class="modal-footer">${footer||`<button class="btn-secondary" data-action="close">Close</button>`}</div></section></div>`;setTimeout(()=>document.querySelector('.modal input:not([type="hidden"]),.modal button')?.focus(),0);}
function closeModal(){modalOpen=false;document.getElementById('modalRoot').innerHTML='';previousFocus?.focus?.();}
function expenseForm(t){const existing=!!t,x=t||{date:state.settings.activeCycle||'2026-10-16',name:'',category:'Food',amount:'',method:'GCash',bucket:'flex',paidBy:'me',otherShare:0,repaid:0,person:''};modal(existing?'Edit transaction':'New expense',existing?'Edit this local sample record.':'Try the complete transaction capture flow.',`<form id="expenseForm" class="form-group"><input type="hidden" name="id" value="${e(x.id||'')}"><div class="form-field wide"><label for="txName">Description / merchant *</label><input id="txName" name="name" placeholder="e.g. Sample dinner" value="${e(x.name)}" required maxlength="100"></div><div class="form-field"><label for="txAmount">Total amount (₱) *</label><input id="txAmount" name="amount" type="number" min="0.01" step="0.01" value="${e(x.amount)}" required></div><div class="form-field"><label for="txDate">Transaction date *</label><input id="txDate" name="date" type="date" value="${e(x.date)}" required></div><div class="form-field"><label for="txCategory">Category</label><select id="txCategory" name="category">${Object.keys(CAT).map(c=>`<option ${x.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-field"><label for="txMethod">Payment method</label><select id="txMethod" name="method">${METHODS.map(m=>`<option ${x.method===m?'selected':''}>${e(m)}</option>`).join('')}</select></div><div class="form-field"><label for="txBucket">Budget allocation</label><select id="txBucket" name="bucket"><option value="flex" ${x.bucket==='flex'?'selected':''}>Discretionary</option><option value="reserve" ${x.bucket==='reserve'?'selected':''}>Existing reserve</option></select></div><div class="form-field"><label for="txPayer">Who paid first?</label><select id="txPayer" name="paidBy"><option value="me" ${x.paidBy==='me'?'selected':''}>I paid</option><option value="other" ${x.paidBy==='other'?'selected':''}>Someone else paid</option></select></div><div class="form-field wide"><div class="modal-section-title">OPTIONAL SHARED EXPENSE</div></div><div class="form-field"><label for="txPerson">Other person's name</label><input id="txPerson" name="person" value="${e(x.person)}" placeholder="Optional" maxlength="70"></div><div class="form-field"><label for="txOther">Other person's share (₱)</label><input id="txOther" name="otherShare" type="number" min="0" step="0.01" value="${e(x.otherShare)}"></div><div class="form-field wide"><label for="txRepaid">Verified repayment (₱)</label><input id="txRepaid" name="repaid" type="number" min="0" step="0.01" value="${e(x.repaid)}"><div class="helper">From them if you paid first; to them if someone else paid. Only include verified payments.</div></div></form><div class="notice-inline">The real app will validate cutoff routing, receipts, split allocations and ledger IDs before any Google Sheets write.</div>`,`<button class="btn-secondary" data-action="close">Cancel</button><button class="btn-primary" data-action="submitExpense">${existing?'Save changes':'Add to demo ledger'}</button>`);}
function detail(id){const t=state.transactions.find(x=>x.id===id);if(!t)return;modal('Transaction details','Saved in this browser only.',`<div style="display:flex;gap:12px;align-items:center;margin-bottom:18px">${categoryIcon(t.category)}<div><strong style="font-size:19px">${e(t.name)}</strong><div style="font-size:11px;color:var(--muted)">${e(niceDate(t.date))}</div></div></div><div class="details-grid"><div><small>Original amount</small><strong>${money(t.amount)}</strong></div><div><small>Budget impact</small><strong class="positive">${money(impact(t))}</strong></div><div><small>Category</small><strong>${e(t.category)}</strong></div><div><small>Payment method</small><strong>${e(t.method)}</strong></div><div><small>Allocation</small><strong>${t.bucket==='reserve'?'Reserved obligation':'Discretionary'}</strong></div><div><small>Paid first</small><strong>${t.paidBy==='me'?'You':'Someone else'}</strong></div><div><small>Shared with</small><strong>${e(t.person||'Not shared')}</strong></div><div><small>Other person share</small><strong>${money(t.otherShare)}</strong></div><div><small>Repayments verified</small><strong>${money(t.repaid)}</strong></div><div><small>Outstanding split</small><strong>${money(balance(t))}</strong></div></div>`,`<button class="danger-button" data-action="deleteTx" data-id="${e(t.id)}">${icon('trash')} Delete</button><button class="btn-secondary" data-action="close">Close</button><button class="btn-primary" data-action="editTx" data-id="${e(t.id)}">${icon('edit')} Edit</button>`);}
function cardPayment(id){const c=state.cards.find(x=>x.id===id);if(!c)return;const remaining=Math.max(0,c.amount-c.paid);modal('Record card payment','Demo issuer payment, not a new expense.',`<form id="cardPaymentForm" class="form-group"><input type="hidden" name="id" value="${e(id)}"><div class="form-field wide"><label>Card</label><input value="${e(c.name)}" disabled></div><div class="form-field"><label>Payment amount (₱)</label><input name="amount" type="number" min="0.01" max="${remaining.toFixed(2)}" step="0.01" value="${remaining.toFixed(2)}" required></div><div class="form-field"><label>Payment date</label><input name="date" type="date" value="2026-11-05" required></div></form><div class="notice-inline">Existing statement: ${money(c.amount)} · Already paid: ${money(c.paid)} · Remaining: ${money(remaining)}</div>`,`<button class="btn-secondary" data-action="close">Cancel</button><button class="btn-primary" data-action="submitCardPay">Record payment</button>`);}
function repay(id){const t=state.transactions.find(x=>x.id===id);if(!t)return;const max=balance(t);modal(t.paidBy==='me'?'Record repayment received':'Record repayment sent','A verified repayment updates only this shared record.',`<form id="repaymentForm" class="form-group"><input type="hidden" name="id" value="${e(id)}"><div class="form-field wide"><label>Transaction</label><input value="${e(t.name)} · ${e(t.person||'Other party')}" disabled></div><div class="form-field"><label>Verified amount (₱)</label><input name="amount" type="number" min="0.01" max="${max.toFixed(2)}" step="0.01" value="${max.toFixed(2)}" required></div></form><div class="notice-inline">Outstanding before payment: ${money(max)}. Pending or unverified transfers should not be recorded here.</div>`,`<button class="btn-secondary" data-action="close">Cancel</button><button class="btn-primary" data-action="submitRepay">Confirm verified payment</button>`);}
function submitExpense(){const f=document.getElementById('expenseForm');if(!f?.reportValidity())return;const d=Object.fromEntries(new FormData(f)),amount=Math.round(num(d.amount)*100)/100,other=Math.round(num(d.otherShare)*100)/100,repaid=Math.round(num(d.repaid)*100)/100,maxRepay=d.paidBy==='other'?amount-other:other;if(!amount||amount<0||other<0||other>amount||repaid<0||repaid>maxRepay){toast('Check amounts: shares and repayments cannot exceed their balances.');return;}if(!/^\d{4}-\d{2}-\d{2}$/.test(d.date)){toast('Enter a valid transaction date.');return;}if(!d.name.trim()){toast('Add a transaction description.');return;}const t={id:d.id||('t'+Date.now().toString(36)+Math.random().toString(36).slice(2,6)),date:d.date,name:d.name.trim().slice(0,100),category:CAT[d.category]?d.category:'Other',amount,method:METHODS.includes(d.method)?d.method:'Cash',bucket:d.bucket==='reserve'?'reserve':'flex',paidBy:d.paidBy==='other'?'other':'me',otherShare:other,repaid,person:String(d.person||'').trim().slice(0,70)};const old=state.transactions.findIndex(x=>x.id===t.id);if(old>=0)state.transactions[old]=t;else state.transactions.push(t);save();closeModal();render();toast(old>=0?'Demo transaction updated.':'Demo transaction recorded.');if(cycleStart(t.date)!==state.settings.activeCycle)toast('Transaction saved. Switch cutoff to '+cycleLabel(cycleStart(t.date))+' to see its budget impact.');}
function submitCardPay(){const f=document.getElementById('cardPaymentForm');if(!f?.reportValidity())return;const d=Object.fromEntries(new FormData(f)),c=state.cards.find(x=>x.id===d.id),amount=Math.round(num(d.amount)*100)/100;if(!c||amount<=0||amount>c.amount-c.paid+.001){toast('Amount exceeds the remaining statement balance.');return;}c.paid=Math.round((c.paid+amount)*100)/100;state.paymentLog.push({id:'p'+Date.now(),cardId:c.id,amount,date:d.date});save();closeModal();render();toast('Card payment recorded separately from expenses.');}
function submitRepay(){const f=document.getElementById('repaymentForm');if(!f?.reportValidity())return;const d=Object.fromEntries(new FormData(f)),t=state.transactions.find(x=>x.id===d.id),amount=Math.round(num(d.amount)*100)/100;if(!t||amount<=0||amount>balance(t)+.001){toast('Amount exceeds this shared balance.');return;}t.repaid=Math.round((t.repaid+amount)*100)/100;save();closeModal();render();toast('Verified demo repayment applied to this transaction.');}
function exportFile(name,type,body){const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export created on this device.');}
function exportCsv(){const head=['Date','Description','Category','Amount PHP','Budget impact PHP','Method','Budget bucket','Paid by','Other person','Other share PHP','Verified repayment PHP','Outstanding shared PHP'],cells=[head,...sortTx().map(t=>[t.date,t.name,t.category,t.amount,impact(t),t.method,t.bucket,t.paidBy,t.person||'',t.otherShare,t.repaid,balance(t)])];exportFile('finance-hq-demo-transactions.csv','text/csv;charset=utf-8','\ufeff'+cells.map(row=>row.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'));}
function importJson(){modal('Import demo backup','Choose a Finance HQ v0.1 JSON export from this prototype.',`<div class="form-field"><label for="importFile">Local JSON backup</label><input id="importFile" type="file" accept=".json,application/json"></div><div class="notice-inline">This replaces the current local demo data after schema checks. It cannot import your real Google Sheets files.</div>`,`<button class="btn-secondary" data-action="close">Cancel</button><button class="btn-primary" data-action="submitImport">Import backup</button>`);}
async function submitImport(){const f=document.getElementById('importFile')?.files?.[0];if(!f){toast('Choose a JSON backup file.');return;}if(f.size>4e6){toast('File too large for this demo.');return;}try{const data=JSON.parse(await f.text());if(!validData(data)||!data.transactions.every(t=>typeof t.name==='string'&&Number.isFinite(Number(t.amount))&&CAT[t.category]&&['me','other'].includes(t.paidBy))){toast('Not a valid Finance HQ demo backup.');return;}state=data;save();closeModal();navigate('home');toast('Demo backup imported locally.');}catch{toast('Could not read this JSON backup.');}}
const handlers={add:()=>expenseForm(),close:closeModal,detail:id=>detail(id),editTx:id=>expenseForm(state.transactions.find(x=>x.id===id)),deleteTx:id=>{if(!confirm('Delete this local demo transaction?'))return;state.transactions=state.transactions.filter(x=>x.id!==id);save();closeModal();render();toast('Demo transaction deleted.');},submitExpense,cardPay:id=>cardPayment(id),submitCardPay,repay:id=>repay(id),submitRepay,billToggle:id=>{const b=state.bills.find(x=>x.id===id);if(b){b.paid=!b.paid;save();render();toast('Demo bill status updated. No transaction was created.');}},rebateToggle:id=>{const r=state.rebates.find(x=>x.id===id);if(r){r.credited=!r.credited;save();render();toast('Demo rebate verification updated.');}},budgetSettings:()=>navigate('settings'),saveSettings:()=>{const val=id=>num(document.getElementById(id)?.value);const cap=val('capSetting'),reserve=val('reserveSetting'),savings=val('savingsSetting');if(cap<=0||reserve<0||savings<0||reserve>1e9||savings>1e9||cap>1e9){toast('Enter sensible positive budget amounts.');return;}state.settings={...state.settings,cap,reserve,savings};save();render();toast('Demo budget settings updated.');},csv:exportCsv,json:()=>exportFile('finance-hq-demo-backup.json','application/json;charset=utf-8',JSON.stringify(state,null,2)),import:importJson,submitImport,reset:()=>{if(!confirm('Reset this browser’s Finance HQ demo? Your real Google Sheets are not affected.'))return;state=demoData();save();filterCategory='all';searchTerm='';navigate('home');toast('Demo restored to initial sample data.');},backdrop:(id,el,event)=>{if(event.target===el)closeModal();}};
document.addEventListener('click',event=>{if(window.FinanceHQLive?.isLive?.()&&event.target.closest('#topAdd,#mobileAdd')){window.FinanceHQLive.refresh();return;}const nav=event.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}const action=event.target.closest('[data-action]');if(action){const h=handlers[action.dataset.action];if(h)h(action.dataset.id,action,event);return;}if(event.target.closest('#topAdd,#mobileAdd')){expenseForm();return;}if(event.target.closest('#searchShortcut')){navigate('activity');(document.getElementById('liveSearch')||document.getElementById('transactionSearch'))?.focus();return;}if(event.target.closest('#mobileMore')){modal('More workspace sections','Jump straight to a finance feature.',`<div style="display:grid;grid-template-columns:1fr 1fr;gap:9px">${[['bills','Bills & installments','calendar'],['shared','Shared expenses','users'],['rebates','Rebates & rewards','sparkles'],['reports','Reports','bars'],['settings','Settings','settings'],['activity','Transactions','list']].map(([key,label,ic])=>`<button class="action-tile" data-nav="${key}">${icon(ic)}${label}</button>`).join('')}</div>`);}});
document.addEventListener('input',event=>{if(event.target.id==='transactionSearch'){searchTerm=event.target.value;const el=document.getElementById('transactionsTableWrap');if(el)el.innerHTML=transactionsTable();}});
document.addEventListener('change',event=>{if(event.target.id==='categorySelect'){filterCategory=event.target.value;document.getElementById('transactionsTableWrap').innerHTML=transactionsTable();}if(event.target.id==='cycleSelect'){state.settings.activeCycle=event.target.value;save();render();}});
document.addEventListener('submit',event=>{if(['expenseForm','cardPaymentForm','repaymentForm'].includes(event.target.id)){event.preventDefault();({expenseForm:submitExpense,cardPaymentForm:submitCardPay,repaymentForm:submitRepay}[event.target.id])();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modalOpen){closeModal();return;}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(modalOpen)closeModal();navigate('activity');(document.getElementById('liveSearch')||document.getElementById('transactionSearch'))?.focus();}if(event.key==='Enter'&&event.target.matches('.trans-row-click')){event.preventDefault();detail(event.target.dataset.id);}if(event.key==='Tab'&&modalOpen){const dialog=document.querySelector('.modal');const focus=[...dialog.querySelectorAll('button:not([disabled]), input:not([disabled]), select:not([disabled])')].filter(x=>x.offsetParent!==null);if(!focus.length)return;const first=focus[0],last=focus[focus.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
if('serviceWorker' in navigator&&/^https?:/.test(location.protocol)){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));}
window.financeHQRender=render;const initial=location.hash.slice(1);view=pages[initial]?initial:'home';render();
})();
